const index = "";
function renderADChart(params) {
  const { chartNumber } = params;
  const suffix = chartNumber ? "_" + chartNumber : "";
  const {
    patient: { age },
    sample: { dateSampled, history },
    diseaseData: { MetaboAD: MetaboAD2 }
  } = window.MetaGuardTWLimsData;
  function renderSummaryTrendChart() {
    const adHistory = history.MetaboAD;
    if (adHistory) {
      const chartData = adHistory.slice(-3).map((o) => {
        const result = o.result;
        const value = result ? result.probability : -9999;
        return {
          testingDate: o.testingDate,
          value,
          levelColor: computeLevelInfo(value, Cutoff.MetaboAD, DiseaseIndexBarColor),
          levelZh: result ? result.qualitativeRisk : ""
        };
      });
      renderSimpleChart({
        containerID: `${ModelKeywords.AD}-simple-chart`,
        containerIDembed: `${ModelKeywords.AD}-simple-chart-embed`,
        data: {
          data: chartData,
          yAxisMax: 100
        }
      });
    }
  }
  if (MetaboAD2) {
    const { index: metaboADIndex, rank: metaboADRank, sameAgeGenderAnalysis, trendAndForecast, heatmap, pathway } = MetaboAD2;
    renderSameAgeGenderInPopulationChart({
      containerID: ChartID.sameAgeGenderRank.ad.id + suffix,
      containerIDembed: ChartID.sameAgeGenderRank.ad.embedId + suffix,
      data: {
        populationRisk: sameAgeGenderAnalysis.differentAgeGroupRisk,
        probability: metaboADIndex.valueNumber,
        age,
        levelColor: sameAgeGenderAnalysis.levelColor
      }
    });
    renderDiseaseTrendingAndPrediction({
      containerID: ChartID.variationTrendAndPredict.ad.id + suffix,
      containerIDembed: ChartID.variationTrendAndPredict.ad.embedId + suffix,
      data: {
        cutoff: metaboADIndex.cutoff,
        trendData: trendAndForecast.data,
        forecastData: trendAndForecast.forecastData
      }
    });
    renderDiseaseIndexContrastChart({
      containerID: ChartID.indexVariationTrend.ad.id + suffix,
      containerIDembed: ChartID.indexVariationTrend.ad.embedId + suffix,
      data: {
        value: metaboADIndex.valueNumber,
        date: dateSampled,
        lastTestValue: metaboADIndex.lastTest && parseFloat(metaboADIndex.lastTest.value),
        lastTestDate: metaboADIndex.lastTest && metaboADIndex.lastTest.testDate,
        predictedValue: trendAndForecast.forecastData[0],
        cutoff: metaboADIndex.cutoff
      }
    });
    renderPopulationRankTrendChart({
      containerID: ChartID.rankVaritationTrend.ad.id + suffix,
      containerIDembed: ChartID.rankVaritationTrend.ad.embedId + suffix,
      data: {
        value: metaboADRank.valueNumber,
        date: dateSampled,
        lastTestValue: metaboADRank.lastTest && parseFloat(metaboADRank.lastTest.value),
        lastTestDate: metaboADRank.lastTest && metaboADRank.lastTest.testDate,
        predictedValue: metaboADRank.forecastData[0]
      }
    });
    renderHeatmapChart({
      containerID: ChartID.heatmap.ad.id + suffix,
      containerIDembed: ChartID.heatmap.ad.embedId + suffix,
      data: {
        heatmapBG: heatmap
      }
    });
    renderSankeyChart({
      containerID: ChartID.sankey.ad.id + suffix,
      containerIDembed: ChartID.sankey.ad.embedId + suffix,
      data: pathway.sankey.data,
      links: pathway.sankey.links
    });
    renderSummaryTrendChart();
  }
}
